// Яркий насыщенный цвет, оттенок меняется со временем + прыгает на бит

function rgb2hsl(r, g, b) {
  max_ = Math.max(r, g, b);
  min_ = Math.min(r, g, b);
  l    = (max_ + min_) / 2;
  if (max_ === min_) return [0, 0, l];
  d = max_ - min_;
  s = l > 0.5 ? d / (2 - max_ - min_) : d / (max_ + min_);
  if (max_ === r) h = (g - b) / d + (g < b ? 6 : 0);
  else if (max_ === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  return [h / 6, s, l];
}

